def routes_command(sort: str, all_methods: bool) -> None:
    """Show all registered routes with endpoints and methods."""

    rules = list(current_app.url_map.iter_rules())
    if not rules:
        click.echo("No routes were registered.")
        return

    ignored_methods = set(() if all_methods else ("HEAD", "OPTIONS"))

    if sort in ("endpoint", "rule"):
        rules = sorted(rules, key=attrgetter(sort))
    elif sort == "methods":
        rules = sorted(rules, key=lambda rule: sorted(rule.methods))  # type: ignore

    rule_methods = [
        ", ".join(sorted(rule.methods - ignored_methods))  # type: ignore
        for rule in rules
    ]

    # If there are any rules with a subdomain, include a Domain column that
    # shows the full domain each route is assigned to.
    has_domain = any(rule.subdomain for rule in rules)

    if has_domain:
        server_name = current_app.config["SERVER_NAME"]

        if server_name is None:
            # Fall back to the first request's host, so subdomains can still
            # be shown even if SERVER_NAME is not configured.
            server_name = current_app.url_map.bind("").server_name
            subdomain = rules[0].subdomain

            if subdomain is None:
                server_name = server_name
            else:
                server_name = server_name.removeprefix(f"{subdomain}.")

        headers = ("Domain", "Endpoint", "Methods", "Rule")
    else:
        headers = ("Endpoint", "Methods", "Rule")

    data_rows = []

    for rule, methods in zip(rules, rule_methods):
        if has_domain:
            domain = (
                f"{rule.subdomain}.{server_name}" if rule.subdomain else server_name
            )
            data_rows.append((domain, rule.endpoint, methods, rule.rule))
        else:
            data_rows.append((rule.endpoint, methods, rule.rule))

    widths = [
        max(len(str(row[i])) for row in [headers, *data_rows])
        for i in range(len(headers))
    ]
    row_format = "  ".join(f"{{{i}:<{{{i}}}}}" for i in range(len(headers)))
    row = row_format.format(*widths)

    click.echo(row.format(*headers).strip())
    click.echo(row.format(*("-" * width for width in widths)))

    for data_row in data_rows:
        click.echo(row.format(*data_row).rstrip())

